  return roomNav()+`<div class="step-title compact"><h1>Detailed room conditions</h1><button class="btn" data-action="conditions-simple">Back to quick conditions</button><p>Record what is visible or confirmed. Choose “Not confirmed yet” when a site check is needed.</p></div>${conditionChoiceBar(r)}
  <section class="panel"><h2>Room construction and access</h2><div class="field-grid spaced">
  ${select('What kind of work is this?',b+'install',r.install,Object.entries(M.BUILDS),'New construction uses rough-in and trim. Retrofit reuses suitable existing fixture locations. Remodel adds or changes locations.')}
  ${select('Finished surface',b+'surfaceMaterial',r.surfaceMaterial,[['unknown','Not confirmed yet'],['open','No finished surface / open framing'],['drywall','Drywall'],['plaster','Plaster / lath']])}
  ${select('Can we reach the ceiling wiring?',b+'ceilingPath',r.ceilingPath||'unknown',[['unknown','Not confirmed yet'],['open','Ceiling framing is or will be open'],['attic','Accessible attic above'],['below','Accessible space below the work'],['closed','Finished and no access above / below']],'An attic must be reachable at the work area, not just present somewhere in the building.')}
  ${select('Can we reach the wall wiring?',b+'wallPath',r.wallPath||'unknown',[['unknown','Not confirmed yet'],['open','Wall framing is or will be open'],['accessible','Accessible cavity / chase to the locations'],['closed','Finished wall with no open route']])}
  ${select('May we open surfaces for wiring?',b+'openingPermission',r.openingPermission||'unknown',permission,'This is permission for extra routing openings. Normal new fixture and box cutouts are part of the selected installation.')}
  ${closed&&!['selective','extensive'].includes(r.openingPermission)&&r.ceilingPath==='closed'?select('Ceiling fishing route',b+'ceilingFishing',r.ceilingFishing||'unknown',fishing):''}
  ${closed&&!['selective','extensive'].includes(r.openingPermission)&&r.wallPath==='closed'?select('Wall fishing route',b+'wallFishing',r.wallFishing||'unknown',fishing):''}
  </div>${warning}${closed?area('What supports the routing decision?',b+'routeEvidence',r.routeEvidence||'','Example: electrician checked the joist bay and wall drop; site visit or photo reference'):''}
  <p class="quiet-note spaced">Access removal is budgeted when permitted. Drywall / plaster repair, reinstatement and painting are excluded.</p></section>${ceilingSuitability(r,b)}
  <section class="panel"><h2>Working conditions</h2><div class="field-grid spaced">
  ${select('Will the room be occupied or furnished?',b+'occupancy',r.occupancy||'unknown',[['unknown','Not confirmed yet'],['vacant','Vacant and clear'],['occupied','Occupied / furnished']])}
  ${select('Working height',b+'ceilingHeight',r.ceilingHeight||'unknown',[['unknown','Not confirmed yet'],['standard','Up to 10 ft, ordinary ladder access'],['tall','Over 10 to 12 ft, clear level floor'],['special','Over 12 ft, stairs, slope or lift needed']])}
  ${select('Other construction conditions',b+'specialConditions',r.specialConditions||'unknown',[['unknown','Not confirmed yet'],['standard','Ordinary framing, no special conditions observed'],['masonry','Masonry / concrete routes'],['rated','Fire-rated assembly / penetrations'],['structural','Structural modification / unusual support'],['hazard','Suspected hazardous material']],'Special conditions require a separate installation method and priced allowance before a customer range is approved.')}
  ${select('Space to carry out the work',b+'access',r.access,[['normal','Normal working space'],['limited','Restricted movement / obstructions'],['difficult','Very restricted movement']])}
  ${hasLighting?select('Lighting power',b+'powerPlan',r.powerPlan,[['existing','Budget around existing circuits'],['new','New lighting circuits needed'],['unknown','Needs a site check']]):''}
  ${select('Wire route length',b+'routeLength',r.routeLength,[['medium','Typical medium runs'],['long','Long / unusually complex runs']])}
  ${(r.decorNew||r.decorExisting)?select('Decorative fixture handling',b+'decorativeComplexity',r.decorativeComplexity||'standard',[['standard','Ordinary fixture and support'],['special','Heavy, fragile or extensive assembly']]):''}</div></section>
  <details class="optional"><summary>Additional control points and plan references</summary><div class="field-grid spaced">${hasLighting?select('Load-control wall location',b+'controlLocation',r.controlLocation,[['existing','Existing control location'],['new','New control location']]):''}${hasLighting?select('Wall control locations per load',b+'controlLocations',r.controlLocations,[[1,'One location'],[2,'Two locations'],[3,'Three locations'],[4,'Four locations']],'Companion wiring must be checked.'):''}${state.project.system==='HomeWorks'?select('Where will lighting loads be controlled?',b+'loadTopology',r.loadTopology,[['distributed','At room wall controls'],['centralized','From a central lighting panel'],['auto','Confirm existing estimate setting']]):''}
  ${field('Drawing / sheet reference',b+'planReference',r.planReference||'','text','Optional estimating handoff reference. This version does not read plans.')}
  ${field('Drawing revision',b+'planRevision',r.planRevision||'')}</div></details>${roomHandoff(r,b)}`;
